<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT t.*,u.name author_name,u.email author_email FROM twibbons t LEFT JOIN users u ON u.id=t.owner_id WHERE t.id=?');$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){http_response_code(404);$title='Karya tidak ditemukan';require __DIR__.'/not-found.php';exit;}$categories=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$title=trim((string)($_POST['title']??''));$description=sanitize_rich_text((string)($_POST['description']??''));$category=(int)($_POST['category_id']??0);$visibility=in_array($_POST['visibility']??'unlisted',['public','unlisted','private'],true)?$_POST['visibility']:'unlisted';$moderation=in_array($_POST['moderation_status']??'approved',['pending','approved','rejected'],true)?$_POST['moderation_status']:'approved';if($title===''||mb_strlen($title)>120)throw new RuntimeException('Judul wajib diisi dan maksimal 120 karakter.');$file=$item['template_image'];if(($_FILES['template_image']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$new=store_image($_FILES['template_image'],__DIR__.'/uploads');$old=__DIR__.'/uploads/'.basename($file);if(is_file($old)&&basename($file)!=='sample_template.png')@unlink($old);$file=$new;}$pdo->prepare('UPDATE twibbons SET title=?,description=?,category_id=?,visibility=?,moderation_status=?,template_image=? WHERE id=?')->execute([$title,$description,$category?:null,$visibility,$moderation,$file,$id]);flash('success','Karya berhasil diperbarui.');redirect('admin');}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Karya — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container edit-page"><div class="page-head"><a class="eyebrow" href="admin">← Kembali ke Kelola Karya</a><h1 class="page-title">Edit karya</h1><p class="subtitle">Atur informasi, kategori, akses, dan moderasi karya.</p></div><?php if(!empty($error)):?><div class="alert alert-error"><?=e($error)?></div><?php endif?><div class="edit-layout"><aside class="panel edit-preview"><img src="uploads/<?=e(basename($item['template_image']))?>" alt=""><div class="author-row"><span class="mini-avatar"><?=e(strtoupper(mb_substr($item['author_name']?:'A',0,1)))?></span><div><small>Dibuat oleh</small><strong><?=e($item['author_name']?:'Data lama')?></strong><small><?=e($item['author_email']?:'Pembuat tidak tercatat')?></small></div></div></aside><section class="panel"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Judul</label><input name="title" value="<?=e($item['title'])?>" required maxlength="120"></div><div class="field"><label>Deskripsi</label><textarea name="description" rows="5"><?=e($item['description'])?></textarea></div><div class="field"><label>Kategori</label><select name="category_id"><option value="">Tanpa kategori</option><?php foreach($categories as $cat):?><option value="<?=(int)$cat['id']?>" <?=$item['category_id']==$cat['id']?'selected':''?>><?=e($cat['name'])?></option><?php endforeach?></select></div><div class="field"><label>Akses</label><select name="visibility"><?php foreach(['public'=>'Publik','unlisted'=>'Via tautan','private'=>'Pribadi'] as $v=>$label):?><option value="<?=$v?>" <?=$item['visibility']===$v?'selected':''?>><?=$label?></option><?php endforeach?></select></div><div class="field"><label>Moderasi</label><select name="moderation_status"><?php foreach(['pending'=>'Menunggu','approved'=>'Disetujui','rejected'=>'Ditolak'] as $v=>$label):?><option value="<?=$v?>" <?=$item['moderation_status']===$v?'selected':''?>><?=$label?></option><?php endforeach?></select></div><div class="field"><label>Ganti gambar <small>(opsional)</small></label><input name="template_image" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="button-row"><a class="btn btn-secondary" href="admin">Batal</a><button class="btn btn-primary">Simpan</button></div></form></section></div></main><footer class="footer">Semarakin · Apins Digital</footer></body></html>
